using System;using System.IO;using System.Reflection;using System.Collections;using System.Security.Cryptography;using System.Text;
class CitationTextTests{
 static Type t;static object Call(string n,params object[] a){try{return t.GetMethod(n,BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,a);}catch(TargetInvocationException e){throw e.InnerException;}}
 static object Get(object o,string n){return o.GetType().GetProperty(n).GetValue(o,null);}static void Check(bool v,string m){if(!v)throw new Exception(m);}
 static string Hash(string p){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(File.ReadAllBytes(p))).Replace("-","");}
 static void Main(string[] args){string root=Path.GetFullPath(args[0]);t=Assembly.LoadFrom(Path.Combine(root,"reader.exe")).GetType("MinerULibraryReview");foreach(var pair in new[]{new[]{"AppDirectory",root},new[]{"StateDirectory",Path.Combine(root,"state")},new[]{"PapersStateDirectory",Path.Combine(root,"state","papers")},new[]{"LibraryRoot",Path.Combine(root,"library")}})t.GetField(pair[0],BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,pair[1]);
 string d=Path.Combine(root,"library","sample");Directory.CreateDirectory(d);Directory.CreateDirectory(Path.Combine(root,"state","papers"));File.WriteAllText(Path.Combine(d,"source.pdf"),"fixture - must not be opened by an external tool");
 string txt=Path.Combine(d,"pdf-text.txt");File.WriteAllText(txt,"PDF 文本提取 · 共 4 页\n页码说明\n\n===== PDF 第 1 / 4 页 =====\nA Reliable Method for Dexterous Manipulation\nAlice Smith, Bob Jones\n2026\nAbstract\nStudy summary\n\n===== PDF 第 2 / 4 页 =====\n10.1234/current.paper\n\n===== PDF 第 3 / 4 页 =====\nThird page\n\n===== PDF 第 4 / 4 页 =====\n10.9999/reference.only\n");
 string header=(string)Call("ReadCitationText",d);Check(!header.Contains("页码说明")&&!header.Contains("PDF 第"),"Remove generated headers");Check(header.Split('\f').Length==3,"Keep page boundaries");Check(!header.Contains("reference.only"),"Exclude fourth page");
 object scan=Call("ScanCitation","sample");Check((string)Get(scan,"title")=="A Reliable Method for Dexterous Manipulation","Extract title from TXT");Check(String.IsNullOrEmpty((string)Get(scan,"warning")),"No external dependency warning");Check(((string)Get(scan,"verificationText")).Contains("Alice Smith"),"Author verification evidence retained");bool current=false,reference=false;foreach(object c in (IEnumerable)Get(scan,"candidates")){current|=(string)Get(c,"doi")=="10.1234/current.paper";reference|=(string)Get(c,"doi")=="10.9999/reference.only";}Check(current&&!reference,"Only initial-page DOI clues");
 File.WriteAllText(Path.Combine(d,"markdown.md"),"# A Different Study on Robotic Learning\n\nCarol White, David Green\n\n10.5678/markdown.paper\n");Check((string)Get(Call("ScanCitation","sample"),"title")=="A Different Study on Robotic Learning","Markdown priority");File.Delete(Path.Combine(d,"markdown.md"));
 string manifest=Path.Combine(d,".paperbench-parsing.json");File.WriteAllText(manifest,"{\"textSignature\":\"old\",\"text\":{\"pdf-text.txt\":\""+Hash(txt)+"\"}}");Check(String.IsNullOrEmpty((string)Call("ReadCitationText",d)),"Reject stale generated TXT");File.Delete(manifest);
 File.WriteAllText(txt,"Manual first page\fManual second page\fManual third page\f10.8888/excluded");Check(!((string)Call("ReadCitationText",d)).Contains("excluded"),"Manual TXT page cap");File.Delete(txt);Check(!String.IsNullOrEmpty((string)Get(Call("ScanCitation","sample"),"warning")),"Missing text gives manual guidance");
 Console.WriteLine("PASS: cached PDF.js TXT without external tools; title/author evidence; page limit; Markdown priority; stale-cache rejection; manual fallback.");}
}
